begin;
-- Maison Academy · harder wrong options: 0007_harder_service (33 cards)
-- Generated by scripts/make_harder_sql.py from content/harder/batch1_service.json.
-- Same questions, facts and right answers; wrong options taken from our own menus and standards.
-- Each card goes back to review. A card is only changed if its right answer still matches the Phase 0
-- export, so anything David has edited since is left alone (listed in the check at the end).

create temporary table _harder (id text primary key, options jsonb, answer jsonb, old_answer jsonb) on commit drop;

update public.cards c set options = h.options, answer = h.answer,
  status = 'review', reviewed_by = null, reviewed_at = null,
  review_note = 'Harder wrong options (0007_harder_service), drafted by Claude 2026-10-17. Same facts and right answer.',
  updated_by = 'Claude (draft for David)'
from _harder h where c.id = h.id and c.status = 'live' and not c.is_allergen
  and public.sorted_jsonb(c.answer) = public.sorted_jsonb(h.old_answer);

update public.card_versions set saved_by = 'Claude (draft for David)' where saved_by = 'System';
update public.audit_log set actor = 'Claude (draft for David)' where actor = 'System' and action = 'card_edited';

select count(*) filter (where c.status = 'review' and c.updated_by = 'Claude (draft for David)') as changed,
       string_agg(h.id, ', ') filter (where not (c.status = 'review' and c.updated_by = 'Claude (draft for David)')) as left_alone
from _harder h join public.cards c using (id);
commit;
